#!/usr/bin/env bash
# 账号入口更新：复制新组件与关键页，然后在 VPS 端对全站执行注入。
set -euo pipefail
echo "== 解包 =="
mkdir -p /tmp/xm-acct-upd && rm -rf /tmp/xm-acct-upd/*
echo '' | base64 -d > /tmp/xm-acct-upd/u.tgz
tar -xzf /tmp/xm-acct-upd/u.tgz -C /tmp/xm-acct-upd

echo "== 复制账号组件 =="
sudo cp /tmp/xm-acct-upd/account-corner.js /var/www/xinmo-site/assets/js/account-corner.js

echo "== 复制手改的关键页 =="
for f in me.html owner.html library.html search.html profile.html; do
  sudo cp /tmp/xm-acct-upd/pages/$f /var/www/xinmo-site/$f
done

echo "== 全站注入账号入口 =="
# 脚本里的 SITE 是本机路径，VPS 上要先改成站点实际目录
sudo sed -i 's|SITE = Path(__file__).resolve().parent.parent / "xinmo-site"|SITE = Path("/var/www/xinmo-site")|' /tmp/xm-acct-upd/inject_account_corner.py
sudo python3 /tmp/xm-acct-upd/inject_account_corner.py

echo "== 校验 =="
grep -c 'account-corner.js' /var/www/xinmo-site/index.html
grep -c 'owner.html' /var/www/xinmo-site/me.html
echo "== DONE =="
